CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(uid INTEGER PRIMARY KEY,kind TEXT NOT NULL,step INTEGER NOT NULL DEFAULT 0,json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS items(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,kind TEXT NOT NULL,title TEXT NOT NULL,done INTEGER NOT NULL DEFAULT 0,changed TEXT,days INTEGER NOT NULL DEFAULT 0,due TEXT,notes TEXT NOT NULL DEFAULT '',amount INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS item_owner ON items(uid,kind,due);
CREATE TABLE IF NOT EXISTS history(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER NOT NULL,item_id INTEGER NOT NULL,changed TEXT NOT NULL,amount INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sent(uid INTEGER NOT NULL,item_id INTEGER NOT NULL,due TEXT NOT NULL,phase TEXT NOT NULL,PRIMARY KEY(uid,item_id,due,phase));
CREATE TABLE IF NOT EXISTS updates(id INTEGER PRIMARY KEY);
